// One item per channel of Config. Fails before any Discord read when Config is not filled in.
const cfg = $('Config').first().json;
const URL_RE = /^https:\/\/discord\.com\/channels\/(\d+|@me)\/(\d+)\/?$/;
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(cfg.email_to ?? '').trim()))
  throw new Error('Config: set email_to to the address that gets the alerts.');
if (!(Number(cfg.messages_per_read) >= 1)) throw new Error('Config: set messages_per_read to 1 or more.');
const channels = String(cfg.channels ?? '').split('\n').map((line) => line.trim()).filter(Boolean).map((line) => {
  const [label, url] = line.includes('|') ? line.split('|').map((s) => s.trim()) : ['', line];
  const m = url.match(URL_RE);
  if (!m) throw new Error(`Config: "${line}" is not "Label | https://discord.com/channels/<server id>/<channel id>".`);
  return { label: label || `Channel ${m[2]}`, url: `https://discord.com/channels/${m[1]}/${m[2]}`, channel: m[2] };
});
if (!channels.length) throw new Error('Config: set channels, one per line.');
return channels.map((json) => ({ json }));

// The messages after the last one recorded for each channel, as one email. A channel seen for the
// first time sends nothing: its newest message is only recorded. Nothing new anywhere: the run ends.
const cfg = $('Config').first().json;
const channels = $('Check Config').all().map(({ json }) => json);
const last = new Map($('Read the last messages sent').all().filter(({ json }) => json.channel)
  .map(({ json }) => [String(json.channel), String(json.last_message_id)]));
const after = (a, b) => BigInt(a) > BigInt(b);
const sections = [];
const positions = [];
let count = 0;
for (const { json: { result } } of $input.all()) {
  const ch = channels.find((c) => c.channel === String(result.channelId));
  if (!ch || !result.messages.length) continue;
  const newest = result.messages[0].messageId;
  const seen = last.get(ch.channel);
  if (seen && !after(newest, seen)) continue;
  positions.push({ channel: ch.channel, last_message_id: newest });
  if (!seen) continue;
  const fresh = result.messages.filter((m) => after(m.messageId, seen)).reverse();
  count += fresh.length;
  const lines = [`== ${ch.label} (${ch.url}) ==`];
  if (fresh.length === result.messages.length && !result.complete)
    lines.push(`More than ${cfg.messages_per_read} messages came since the last check: open the channel to read the others.`);
  for (const m of fresh) {
    const who = m.authorDisplayName && m.authorDisplayName !== m.author ? `${m.authorDisplayName} (${m.author})` : m.author ?? 'Unknown';
    lines.push('', `${m.timestamp.slice(0, 16).replace('T', ' ')} UTC - ${who}`);
    if (m.replyTo?.author) lines.push(`Reply to ${m.replyTo.author}: ${String(m.replyTo.content ?? '').slice(0, 120)}`);
    if (m.content) lines.push(m.content);
    for (const a of m.attachments ?? []) lines.push(`Attachment: ${a.filename} ${a.url}`);
    for (const e of m.embeds ?? []) lines.push(`Embed: ${[e.title, e.url].filter(Boolean).join(' ')}`);
    lines.push(`Link: ${ch.url}/${m.messageId}`);
  }
  sections.push({ label: ch.label, text: lines.join('\n') });
}
if (!positions.length) return [];
const email = count
  ? {
      subject: `Discord: ${count} new message${count > 1 ? 's' : ''} in ${sections.map((s) => s.label).join(', ')}`,
      body: sections.map((s) => s.text).join('\n\n') + '\n\nAttachment links expire after about a day.',
    }
  : null;
return [{ json: { email, positions } }];
